const STY = (bg) => `position:absolute;left:70px;width:800px;height:180px;display:flex;align-items:center;justify-content:center;text-align:center;border-radius:46px;box-shadow:0 26px 40px -14px rgba(0,0,0,.5),inset 0 4px 0 rgba(255,255,255,.5);background:${bg};color:#0b1020;font-family:inherit;font-weight:900;font-size:62px;opacity:0;box-sizing:border-box;padding:0 40px;`;
const L1 = `linear-gradient(180deg, #ffffff, color-mix(in srgb, var(--acc) 30%, #fff))`;
const L2 = `linear-gradient(180deg, #ffffff, color-mix(in srgb, var(--acc2) 30%, #fff))`;

root.innerHTML = `
  <div id="c0" style="${STY(L1)};top:100px;">PYTHON TASKS</div>
  <div id="c1" style="${STY(L2)};top:315px;">100x FASTER</div>
  <div id="c2" style="${STY(L1)};top:530px;">DATA VERIFIED</div>
  <div id="c3" style="${STY(L2)};top:745px;">ZERO ERRORS</div>
  <div id="speed-bg" style="position:absolute;left:70px;top:315px;width:0px;height:180px;background:var(--acc2);border-radius:46px;opacity:0.2;z-index:-1;"></div>
`;

const els = [0, 1, 2, 3].map(i => root.querySelector('#c' + i));
const speedBar = root.querySelector('#speed-bg');

function frame(t, p, d) {
  // Sequence timings (p-based, scaled by 7s duration)
  const s0 = spr(t, 0.4, 0.85, 10);
  const s1 = spr(t, 1.2, 0.85, 10);
  const s2 = spr(t, 2.0, 0.85, 10);
  const s3 = spr(t, 2.8, 0.85, 10);

  // Python Tasks: Slides in from left
  els[0].style.opacity = s0;
  els[0].style.transform = `translateX(${lerp(-60, 0, s0)}px)`;

  // 100x Faster: Drops from behind card 0
  els[1].style.opacity = s1;
  els[1].style.transform = `translateY(${lerp(-40, 0, s1)}px) scale(${lerp(0.9, 1, s1)})`;
  speedBar.style.opacity = s1 * 0.3;
  speedBar.style.width = `${lerp(0, 800, E_OUT(clamp((p - 0.2) * 4)))}px`;

  // Data Verified: Slides in from right
  els[2].style.opacity = s2;
  els[2].style.transform = `translateX(${lerp(60, 0, s2)}px)`;

  // Zero Errors: Pops up with a scale effect
  els[3].style.opacity = s3;
  els[3].style.transform = `translateY(${lerp(40, 0, s3)}px) scale(${lerp(0.8, 1, s3)})`;

  // Group settling move
  const groupY = E_INOUT(clamp(p * 2)) * -20;
  root.style.transform = `translateY(${groupY}px)`;

  // Maintain stillness after p=0.55
  if (p > 0.55) {
    const hold = 1;
    els[0].style.opacity = hold;
    els[1].style.opacity = hold;
    els[2].style.opacity = hold;
    els[3].style.opacity = hold;
    els[0].style.transform = 'translateX(0px)';
    els[1].style.transform = 'translateY(0px) scale(1)';
    els[2].style.transform = 'translateX(0px)';
    els[3].style.transform = 'translateY(0px) scale(1)';
    speedBar.style.width = '800px';
    root.style.transform = `translateY(-20px)`;
  }
}
